 if(g==='Hip-Hop'){names=NAMES;cnt=CNT;artK=ART}else{const set=new Set();let i=0;while(set.size<n){set.add(FN[((h0>>>0)+i*7)%FN.length]+' '+LN[(h0>>>((3+i*5)%29)+i)%LN.length]);i++}names=[...set].sort();cnt=names.map((_,i)=>5+((h0>>>((i%8)+i))%9));artK=names.map((_,i)=>[...arts,'d'+(1+(h0+i)%10)][i%(arts.length+1)])}
