function noteEdit(k){const p=$('pop'),s=S[k];p.innerHTML=`<div class="cap">Note on ${s.t}</div><div class="snote"><textarea id="snTx" maxlength="140" rows="3" placeholder="Where were you? Who's it about? Only you see this.">${NOTES[k]||''}</textarea><div class="snote-a"><span class="m mut" id="snN">${(NOTES[k]||'').length}/140</span>${NOTES[k]?'<button class="btn gh sm" data-snd>Delete</button>':''}<button class="btn pri sm" data-sns="${k}">Save</button></div></div>`;p.classList.add('open');const t=$('snTx');t.focus();t.oninput=()=>{$('snN').textContent=t.value.length+'/140'};t.onkeydown=e=>{e.stopPropagation();if(e.key==='Enter'&&(e.metaKey||e.ctrlKey))p.querySelector('[data-sns]').click();if(e.key==='Escape')p.classList.remove('open')};p.dataset.nk=k}
document.addEventListener('click',e=>{let x;const p=$('pop');
 if(x=e.target.closest('[data-snote]')){e.stopPropagation();return noteEdit(x.dataset.snote)}
 if(x=e.target.closest('[data-sns]')){e.stopPropagation();const k=x.dataset.sns,v=$('snTx').value.trim(),o=NOTES[k];v?NOTES[k]=v:delete NOTES[k];p.classList.remove('open');if($('np').classList.contains('open'))npBuild();return toast(v?'Note saved \u00b7 only you see it':'Note removed','Undo',()=>{o?NOTES[k]=o:delete NOTES[k];if($('np').classList.contains('open'))npBuild();$('toast').classList.remove('open')})}
 if(x=e.target.closest('[data-snd]')){e.stopPropagation();const k=p.dataset.nk,o=NOTES[k];delete NOTES[k];p.classList.remove('open');if($('np').classList.contains('open'))npBuild();return toast('Note removed','Undo',()=>{NOTES[k]=o;if($('np').classList.contains('open'))npBuild();$('toast').classList.remove('open')})}
 if(e.target.closest('.snote'))e.stopPropagation()},true);
{const _na=npAbout;npAbout=function(){const k=curK(),h=_na(),n=NOTES[k];const note=n?`<button class="npnote" data-snote="${k}"><span class="cap">Your note</span><q>${n.replace(/</g,'&lt;')}</q></button>`:`<button class="npnote add" data-snote="${k}">${ICON('plus')}Add a private note to this song</button>`;const i=h.indexOf('<dl class="npd">');return i<0?h:h.slice(0,i)+note+h.slice(i)}}
